const API='https://hacker-news.firebaseio.com/v0';
const $=selector=>document.querySelector(selector);
let stories=[];
let filter='all';
const topicRules={ai:/\b(ai|llm|model|openai|anthropic|machine learning|neural|agent|chatgpt)\b/i,security:/\b(security|vulnerab|exploit|breach|ransomware|password|malware|privacy|cyber|cve)\b/i,engineering:/\b(programm|developer|software|code|github|linux|database|compiler|web|browser|rust|python|javascript|api|open source|engineering)\b/i};
function topic(title){return Object.entries(topicRules).filter(([,rule])=>rule.test(title)).map(([name])=>name)}
function age(unix){const minutes=Math.max(1,Math.floor((Date.now()-unix*1000)/60000));if(minutes<60)return `${minutes} MIN AGO`;const hours=Math.floor(minutes/60);return hours<24?`${hours} HR AGO`:`${Math.floor(hours/24)} DAY AGO`}
function source(item){try{return new URL(item.url).hostname.replace(/^www\./,'').toUpperCase()}catch{return 'HACKER NEWS'}}
function render(){const list=filter==='all'?stories:stories.filter(item=>item.topics.includes(filter));const host=$('#stories');host.replaceChildren();$('#story-count').textContent=`${list.length} STORIES`;$('#feed-status').textContent=list.length?'':`No ${filter} stories in this feed right now. Choose another topic or refresh.`;if(!list.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='No stories found in this topic right now.';host.append(empty);return}list.forEach((item,index)=>{const card=document.createElement('a');card.className=`story-card${filter==='all'&&index===0?' featured':''}`;card.href=item.url||`https://news.ycombinator.com/item?id=${item.id}`;card.target='_blank';card.rel='noopener noreferrer';const top=document.createElement('div');top.className='story-top';const number=document.createElement('span');number.className='story-number';number.textContent=String(index+1).padStart(2,'0')+' / '+(item.topics[0]||'TECH').toUpperCase();const arrow=document.createElement('span');arrow.className='story-action';arrow.textContent='↗';top.append(number,arrow);const title=document.createElement('h3');title.textContent=item.title;const meta=document.createElement('div');meta.className='story-meta';const time=document.createElement('span');time.textContent=age(item.time);const domain=document.createElement('span');domain.textContent=source(item);meta.append(time,domain);card.append(top,title,meta);host.append(card)})}
async function load(){const button=$('#refresh');button.disabled=true;$('#feed-status').textContent='Connecting to the latest stories…';try{const response=await fetch(`${API}/topstories.json`);if(!response.ok)throw Error('Story list unavailable');const ids=(await response.json()).slice(0,36);const items=await Promise.all(ids.map(async id=>{try{const result=await fetch(`${API}/item/${id}.json`);return result.ok?await result.json():null}catch{return null}}));stories=items.filter(item=>item&&item.type==='story'&&item.title).map(item=>({...item,topics:topic(item.title)}));if(!stories.length)throw Error('No stories available');$('#updated-at').textContent=`UPDATED ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;render()}catch(error){$('#feed-status').textContent='The live feed could not load. Please try again.';$('#story-count').textContent='FEED UNAVAILABLE';if(!stories.length)$('#stories').replaceChildren()}finally{button.disabled=false}}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(tab=>{const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-pressed',String(active))});render()}));
$('#refresh').addEventListener('click',load);
load();
